data.query:
query Query($where: ProductionSetupOutputWhereInput, $orderBy: [ProductionSetupOutputOrderByInput!], $first: Int, $after: String) {

  productionSetupOutput(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        setupBoms{edges{node{id}}}
        productionSetup {
          id
          modeId
          outputs {
            total
          }
        }
        workcenter {
          id
          modeGroup {
             modeList(where: {defaultNoSetup: {_eq: true}}) {
              edges {
                node {
                  mode {
                    id
                    requireEvent
                    defaultEventId
                  }
                }
              }
            }
          }  
        }
        producedQuantity
        scrappedQuantity
        counterInput
        cycleTime
        distributionQuantity
        idealRate
        remainingBalance
        setupRate
        standardRate
        startAt
        unitPerCycle
        productId
        productStrategyProcessId
        workOrderDistribution {
          distributionGroupId
          id
          balanceQuantity
          requiredQuantity
          producedQuantity
          productionOperators
          workOrderProcessDistributionStatusId
          setupOperators
          averageRate
          cycleTime
          dispatchSequence
          idealRate
          quotedRate
          setupRate
          standardRate
          workOrderProcessId
          assetId
          workOrderId
          workcenterId
        }
        workOrderId
        workOrderProcessId

        setupBoms {
          edges {
            node {
              id

            }
          }
        }

      }
    }
  }
}

data.variablesTransform:
(

$t := $now();
{
  "deletePayload": {
    "where": {"id":$state.context.SETUP.id}
  },
  "createPayload": {
    "create": {
       "message": "Production Output " & $state.context.SETUP.id & " cleared from workcenter " & $state.context.SETUP.workcenter.id,
       "occurAt": $t,
       "workcenterId": $state.context.SETUP.workcenter.id,
       "transactionTypeId": "Production Setup Clear"
    }
  },
  "updatePayload": {
    "update": {
      "endAt": $t,
      "duration": $toMillis($t) - $toMillis($state.context.HISTORY.occurAt)
    },
    "where": {
      "id": $state.context.HISTORY.id
    }
  }
}

)

data.query:
query Query($where: WorkcenterHistoryWhereInput, $orderBy: [WorkcenterHistoryOrderByInput!], $first: Int, $after: String) {
  workcenterHistory(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        distributionId
        duration
        endAt
        occurAt
        transactionTypeId
      }
    }
  }
}

query Query($where: WorkOrderWhereInput, $orderBy: [WorkOrderOrderByInput!], $first: Int, $after: String) {
  workOrder(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        workOrderStatusId
        workOrderDistributions {
          edges {
            node {
              id
              workOrderProcessDistributionStatusId
            }
          }
        }
        workOrderProcesses {
          edges {
            node {
              id
              workOrderProcessStatusId
            }
          }
        }
      }
    }
  }
}

query Query($whereH:WorkcenterHistoryWhereInput) {
   workcenterHistory(where: $whereH, orderBy: {field: occurAt, direction: desc}, first: 1) {
    edges {
      node {
        id
        distributionId
        duration
        endAt
        occurAt
        transactionTypeId
      }
    }
  }

}

